import jwt
import datetime
import base64
import numpy as np

SECRET_KEY = 'your_secret_key'  # Replace with your own secret key
ALGORITHM = 'HS256'

def create_token(payload):
    if not SECRET_KEY:
        SECRET_KEY = base64.urlsafe_b64encode(np.random.bytes(32)).decode('utf-8')

    encoded_payload = jwt.encode(
        payload,
        SECRET_KEY,
        algorithm=ALGORITHM
    )

    return encoded_payload.decode('utf-8')

def verify_token(token):
    try:
        decoded_payload = jwt.decode(
            token,
            SECRET_KEY,
            algorithms=[ALGORITHM]
        )
        return decoded_payload
    except jwt.ExpiredSignatureError:
        print("Token has expired.")
    except jwt.InvalidTokenError:
        print("Invalid token.")
    except jwt.DecodeError:
        print("Error during token decoding.")

    return None
