 Here's the Python code for the two functions `serialize_message` and `deserialize_message` that convert a dict `msg` to `bytes` for sending and convert received `bytes` back into the dict. The code uses the `pickle` module for serialization/deserialization and ensures that only serializable items are used.

```python
import pickle
import json

def is_serializable(obj):
    """
    Check if an object can be pickled (serialized)
    """
    try:
        pickle.dumps(obj)
    except TypeError:
        return False
    return True

def serialize_message(msg):
    """
    Convert a dict into bytes for sending
    """
    serializable_msg = {}

    for key, value in msg.items():
        if is_serializable(value):
            serializable_msg[key] = value
        elif isinstance(value, (list, dict)):
            serializable_list = []
            for item in value:
                if is_serializable(item):
                    serializable_list.append(item)
            serializable_msg[key] = serializable_list
        else:
            serializable_msg[key] = json.dumps(value)

    serialized_data = pickle.dumps(serializable_msg)
    return serialized_data

def deserialize_message(raw):
    """
    Convert received bytes back into the dict
    """
    try:
        deserialized_data = pickle.loads(raw)
    except (TypeError, EOFError, pickle.UnpicklingError):
        return None

    deserialized_dict = {}
    for key, value in deserialized_data.items():
        if isinstance(value, (list, dict)):
            deserialized_list = []
            for item in value:
                if isinstance(item, str):
                    deserialized_list.append(json.loads(item))
                else:
                    deserialized_list.append(item)
            deserialized_dict[key] = deserialized_list
        else:
            deserialized_dict[key] = value

    return deserialized_dict
```

