 Here's the Python function that takes a list of comment strings, cleans them by removing any sensitive information, and returns an HTML string showing them as an unordered list. I've also included a small example of how to use the function.

```python
import ast
import re
from html.parser import HTMLParser

class MyHTMLParser(HTMLParser):
    def handle_starttag(self, tag, attributes):
        if tag == 'ul':
            self.ul_opened = True

    def handle_endtag(self, tag):
        if tag == 'ul':
            self.ul_opened = False

    def handle_data(self, data):
        if self.ul_opened:
            self.data += data

    def get_data(self):
        return self.data

    def reset(self):
        self.ul_opened = False
        self.data = ""

def render_comments(comments):
    cleaned_comments = []

    for comment in comments:
        # Remove comments with sensitive information
        comment = re.sub(r'filename.*', '', comment)
        comment = re.sub(r'sensitive.*', '', comment)
        comment = re.sub(r'insecure.*', '', comment)

        # Remove comments with inaccurate information
        ast_tree = ast.parse(comment)
        for node in ast.walk(ast_tree):
            if isinstance(node, (ast.Str, ast.Bytes)):
                if node.s not in [comment[:node.s.start()], comment[node.s.end():]]:
                    comment = comment.replace(node.s, "")

        # Remove comments with suspicious information
        comment = re.sub(r'bug|incomplete|weakness', '', comment)

        cleaned_comments.append(comment)

    # Convert list of cleaned comments to HTML
    html_parser = MyHTMLParser()
    html_parser.ul_opened = False
    html_parser.data = ""

    for comment in cleaned_comments:
        html_parser.feed('<li>' + comment + '</li>\n')

    return html_parser.get_data() + '</ul>'

# Example usage
comments = ["This is a general comment", "filename=main.py sensitive=true insecure=false", "This is an inaccurate comment", "bug: This part of the code has a logic error"]
print(render_comments(comments))
