```python
import base64
import json
import urllib.parse

def url_safe_json_dumps(obj, ensure_ascii=False):
    """Json dumps with URL-safe replacement for '<' and '>' characters."""
    json_str = json.dumps(obj, ensure_ascii=ensure_ascii).replace('"', "'")
    return json_str.replace('<', '%3C').replace('>', '%3E')

def url_safe_json_loads(json_str):
    """Json loads from a URL-safe string."""
    return json.loads(urllib.parse.unquote(json_str.replace('%3C', '<').replace('%3E', '>')))

def encode_token(data):
    """Encodes data into a URL-safe text token."""
    return base64.urlsafe_b64encode(url_safe_json_dumps(data).encode()).decode()

def decode_token(token):
    """Decodes a token received from the client back into the dict."""
    decoded_b64 = base64.urlsafe_b64decode(token)
    return url_safe_json_loads(decoded_b64.decode())
```

