import json
import uuid

def urlsafe_b64encode(data):
    return base64.urlsafe_b64encode(data).decode('ascii').replace('+', '-').replace('/', '_')

def urlsafe_b64decode(data):
    return base64.urlsafe_b64decode(data.replace('-', '+').replace('_', '/'))

