    token_list = json.loads(token.replace('_', ':').replace('-', '+').replace('_', '/').replace('\\', '').replace('\'', '"').replace(']', '}'))
    if isinstance(token_list, dict):
        return token_list
    else:
        return urlsafe_b64decode(token)

