```python
import re

def render_comments(comments):
    def is_sensitive_comment(comment):
        sensitive_keywords = ['filename', 'web', 'password', 'secret']
        for keyword in sensitive_keywords:
            if keyword in comment.lower():
                return True
        return False

    def check_comment_style(comment):
        comment_start = re.search(r'#\s*', comment)
        comment_end = re.search(r'\s*$', comment)

        if not comment_start or not comment_end:
            return False

        return len(comment) > len(comment_start.group()) + len(comment_end.group())

    def prune_excessive_commented_code(comment):
        comment_start = re.search(r'#\s*', comment)
        comment_end = re.search(r'#.*$', comment)

        if not comment_end:
            return ''

        uncommented_code = comment[:comment_start.start()] + comment[comment_end.end():]
        return uncommented_code if uncommented_code else ''

    html_comments = '<ul>\n'
    for comment in comments:
        if not is_sensitive_comment(comment) and check_comment_style(comment):
            pruned_comment = prune_excessive_commented_code(comment)
            html_comments += f'<li>{pruned_comment}</li>\n'

    html_comments += '</ul>'
    return html_comments
```

