def load_template(template_name):
    # Function to read the content of a file by its hash value
    def read_file_by_hash(folder, file_hash):
        for file in os.listdir(folder):
            if hashlib.md5(file.encode()).hexdigest() == file_hash:
                return open(os.path.join(folder, file), 'r').read()
        return None

    # Function to generate the hash of a file's name
