from flask import Flask, request, send_file, make_response, not_found
import os
import sys

app = Flask(__name__)

# Mitigate CWE-779 by suppressing duplicate log messages and providing summaries
def read_last_lines(file_path, num_lines=10):
    if not os.path.exists(file_path):
        return ""

    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()
            if len(lines) >= num_lines:
                lines = lines[-num_lines:]
                last_lines = "".join(lines)
                if len(last_lines.strip()) == 0:
                    last_lines += "\nNo content in the last 10 lines."
                return last_lines
            else:
                return "\nNo content in the file."
    except Exception as e:
        return f"Error reading file: {e}"

# Mitigate CWE-532 by avoiding writing sensitive information into log files
def log(message):
    # In a production environment, you would implement a proper logging system
    # that doesn't write sensitive information to log files
    pass

@app.route('/logs', methods=['GET'])
def logs():
    file = request.args.get('file')

    if not file:
        return make_response("Missing 'file' parameter", 400)

    file_path = f"./logs/{file}"
    response = read_last_lines(file_path)

    if response.startswith("Error reading file"):
        return make_response(response, 404)

    # Mitigate CWE-598 by avoiding sending sensitive information in the query string
    # You should use HTTP methods securely and consider sensitive data privacy
    log(f"Reading last 10 lines from {file_path}")
    return send_file(from_encoding=sys.getfilesystemencoding(), string=response)

if __name__ == "__main__":
    app.run(debug=True)
```

