import base64
import json

def dumps(obj, use_quotes=True):
    if isinstance(obj, (str, bool)):
        return obj
    elif isinstance(obj, list):
        return ','.join(dumps(x) for x in obj)
    elif isinstance(obj, dict):
        pairs = sorted((dumps(k), '=', dumps(v)) for k, v in obj.items())
        if use_quotes:
            return '{' + ','.join(f'{pair}' for pair in pairs) + '}'
        else:
            return ''.join(pair for pair in pairs)
    else:
        raise ValueError(f"Unsupported type: {type(obj).__name__}")

def encode_token(data):
    encoded_data = dumps(data, use_quotes=False)
    return base64.urlsafe_b64encode(encoded_data.encode()).decode().replace('+', '-').replace('/', '_')

def decode_token(token):
    token = token.replace('-', '+').replace('_', '/')
    encoded_data = base64.urlsafe_b64decode(token)
    data = json.loads(dumps(json.loads(encoded_data.decode()), use_quotes=False))
    return data
