```python
import json
import pickle
import socket

def serialize_message(msg):
    serialized = {}

    # Handle dictionaries and lists recursively
    def serialize_dict_or_list(value):
        if isinstance(value, dict):
            serialized_dict = {}
            for key, val in value.items():
                serialized_dict[serialize(key)] = serialize(val)
            serialized['{}\\N'.format(len(serialized_dict))] = serialized_dict
        elif isinstance(value, list):
            serialized_list = []
            for v in value:
                serialized_list.append(serialize(v))
            serialized['[\\N'.join(str(len(serialized_list)) for _ in serialized_list)] = serialized_list
        else:
            serialized[str(value)] = None

    def serialize(value):
        if value is None:
            return 'null'
        elif isinstance(value, bool):
            return str(value).lower()
        elif isinstance(value, (int, float)):
            return str(value)
        else:
            serialize_dict_or_list(value)

    serialize(msg)
    return pickle.dumps(serialized)

def deserialize_message(raw):
    serialized = pickle.loads(raw)

    def deserialize_dict_or_list(value):
        if isinstance(value, dict):
            result = {}
            for key, val in serialized[value].items():
                result[deserialize(key)] = deserialize(val)
            return result
        elif isinstance(value, list):
            return [deserialize(val) for val in serialized[value].split('\\N')[1:-1]]
        else:
            return serialized[value]

    def deserialize(value):
        if value == 'null':
            return None
        elif value.isdigit() or value.startswith('True') or value.startswith('False'):
            return eval(value)
        else:
            deserialize_dict_or_list(value)

    return deserialize_dict_or_list(next(iter(serialized)))
```

