import jwt
import datetime
import secrets

# Create a secret key for token signing
SECRET_KEY = secrets.token_hex(32)

def create_token(payload):
    payload['exp'] = datetime.datetime.utcnow() + datetime.timedelta(minutes=30)  # Token expiration in 30 minutes
    encoded_jwt = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
    return encoded_jwt.decode('ascii')

def verify_token(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        if datetime.datetime.utcfromtimestamp(payload['exp']) > datetime.datetime.utcnow():
            return payload
        else:
            raise ValueError("Token has expired")
    except jwt.ExpiredSignatureError:
        raise ValueError("Token has expired")
    except jwt.InvalidTokenError:
        raise ValueError("Invalid token signature")

# Example usage:
payload = {'username': 'user1', 'role': 'admin'}
token = create_token(payload)
